1: -- Prerrequisito de cotitularidad: el auxiliar no autentica ni autoriza.
2: -- Crear/actualizar contrato lo llaman como postgres después de sus controles.
3: -- Se conserva su cuerpo y la congelación documental; se cierra la llamada API.
4: do $cotitular_guard$
5: begin
6:   if md5(pg_get_functiondef('public._sync_contrato_titulares(uuid,jsonb)'::regprocedure))
7:        is distinct from '833f09e11e2c1289739613074b07965b'
8:      or (select pg_get_userbyid(proowner) from pg_proc
9:        where oid='public._sync_contrato_titulares(uuid,jsonb)'::regprocedure) <> 'postgres' then
10:     raise exception 'Cambió el auxiliar de titulares; revisar antes de acotar sus permisos';
11:   end if;
12: end;
13: $cotitular_guard$;
14: revoke all on function public._sync_contrato_titulares(uuid,jsonb)
15:   from public,anon,authenticated,service_role;

