1: import assert from 'node:assert/strict';
2: import { createHash } from 'node:crypto';
3: import { readFileSync, writeFileSync } from 'node:fs';
4: import { crearCopiaSql } from './copia-sql-local.mjs';
5: import { sql as sqlOriginal, literal as q, leer } from './banco-local.mjs';
6: import { contratoPrueba } from './operaciones-fixture.mjs';
7: const tablas=['public.contratos','public.contrato_titulares','public.cronograma_pagos','private.contrato_pdfs',
8:   'crm.inversiones','crm.inversion_titulares','auth.users','public.perfiles'];
9: const foto=`select jsonb_object_agg(tabla,huella) from (${tablas.map(t=>`select ${q(t)} tabla,
10:   private.idem_hash(coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]')) huella from ${t} t`).join(' union all ')}) x`;
11: const original=sqlOriginal(foto),copia=crearCopiaSql('cotitular_puerta'),{sql,abrirSesion}=copia;
12: assert.equal(sql(foto),original);
13: const modulo=readFileSync(new URL('./09-cotitular-puerta.sql',import.meta.url),'utf8');
14: const funcionesSql=`select jsonb_object_agg(oid::regprocedure::text,md5(pg_get_functiondef(oid))) from pg_proc
15:   where oid in ('public._sync_contrato_titulares(uuid,jsonb)'::regprocedure,
16:     'public.crear_contrato(jsonb,jsonb)'::regprocedure,'public.actualizar_contrato(uuid,jsonb,jsonb)'::regprocedure)`;
17: const cuerpos=JSON.parse(sql(funcionesSql)),pruebas=[];
18: const f=leer('fixtures.json');
19: const contratoBase=sql("select id from public.contratos where numero_contrato='F4-BASE-INICIAL'");
20: const perfil=sql(`select cliente_id from public.contratos where id=${q(contratoBase)}`);
21: const datos=contratoPrueba(perfil,f.usuarios.vendedor.id,{inicio:'2026-09-01'});
22: const titular={nombre_completo:'COTITULAR FICTICIO PUERTA',tipo_documento:'DNI',documento:'98765432'};
23: datos.contrato.titulares=[titular];
24: const claims=q(JSON.stringify({sub:f.usuarios.gerencia.id,role:'authenticated'}));
25: const como=sentencia=>sql(`begin;set local request.jwt.claims=${claims};set local role authenticated;${sentencia};commit;`);
26: async function rechazar(rol,consulta,patron){
27:  const s=abrirSesion('f4_cotitular_negativo');s.enviar('\\set VERBOSITY verbose');
28:  s.enviar(`begin;set local request.jwt.claims='{}';set local role ${rol};${consulta};`);
29:  const r=await s.cerrar('rollback;');assert.notEqual(r.codigo,0);assert.match(r.error,patron);return r;
30: }
31: try {
32:   sql(`begin;${modulo}commit;`);
33:   assert.deepEqual(JSON.parse(sql(funcionesSql)),cuerpos);
34:   const fotoCerrada=sql(foto);
35:   for(const rol of ['anon','authenticated','service_role']){
36:     assert.equal(sql(`select has_function_privilege(${q(rol)},'public._sync_contrato_titulares(uuid,jsonb)','EXECUTE')`),'f');
37:     await rechazar(rol,`select public._sync_contrato_titulares(${q(contratoBase)},${q(JSON.stringify([titular]))})`,/42501:.*permission denied for function _sync_contrato_titulares/);
38:     pruebas.push({nombre:`Llamada directa ${rol} rechazada`,sqlstate:'42501'});
39:   }
40:   assert.equal(sql(foto),fotoCerrada,'Los rechazos no cambian las fuentes');
41:   const r=JSON.parse(como(`select public.crear_contrato(${q(JSON.stringify(datos.contrato))},${q(JSON.stringify(datos.cronograma))})`));
42:   assert(r.id);
43:   assert.equal(sql(`select count(*) from public.contrato_titulares where contrato_id=${q(r.id)}`),'1');
44:   pruebas.push({nombre:'Alta autorizada crea contrato y cotitular mediante helper interno',contrato:r.id});
45:   const payload=JSON.parse(sql(`select to_jsonb(c) from public.contratos c where id=${q(r.id)}`));
46:   payload.titulares=[{...titular,nombre_completo:'COTITULAR FICTICIO CORREGIDO'}];
47:   como(`select public.actualizar_contrato(${q(r.id)},${q(JSON.stringify(payload))},null)`);
48:   assert.equal(sql(`select nombre_completo from public.contrato_titulares where contrato_id=${q(r.id)}`),'COTITULAR FICTICIO CORREGIDO');
49:   pruebas.push({nombre:'Corrección autorizada conserva el circuito de titulares'});
50:   const antesRechazo=sql(foto);
51:   await rechazar('anon',`select public.actualizar_contrato(${q(r.id)},${q(JSON.stringify(payload))},null)`,/42501/);
52:   await rechazar('anon',`select public.crear_contrato(${q(JSON.stringify(datos.contrato))},${q(JSON.stringify(datos.cronograma))})`,/42501/);
53:   assert.equal(sql(foto),antesRechazo);
54:   pruebas.push({nombre:'Puertas canónicas rechazan usuario sin sesión, sin efectos'});
55:   const congelado=sql("select id from public.contratos where numero_contrato='F4-BASE-UPGRADE-ELEGIBLE'");
56:   const cerrado=JSON.parse(sql(`select to_jsonb(c) from public.contratos c where id=${q(congelado)}`));cerrado.titulares=[titular];
57:   const s=abrirSesion('f4_cotitular_pdf');s.enviar('\\set VERBOSITY verbose');
58:   s.enviar(`begin;set local request.jwt.claims=${claims};set local role authenticated;
59:     select public.actualizar_contrato(${q(congelado)},${q(JSON.stringify(cerrado))},null);`);
60:   const neg=await s.cerrar('rollback;');assert.notEqual(neg.codigo,0);assert.match(neg.error,/55000/);
61:   assert.equal(sql(foto),antesRechazo);
62:   pruebas.push({nombre:'La congelación documental sigue impidiendo modificar cotitulares'});
63:   assert.deepEqual(JSON.parse(sql(funcionesSql)),cuerpos);
64: } finally {assert.equal(sqlOriginal(foto),original,'Banco original sin cambios');}
65: writeFileSync(new URL(`../evidencia-f4/cotitular-puerta-${copia.id}.json`,import.meta.url),JSON.stringify({
66:   entorno:'avancecorp-f4-bank',baseCopia:copia.nombre,terminadoEn:new Date().toISOString(),pruebas,
67:   cuerposSinModificar:cuerpos,sha256Modulo:createHash('sha256').update(modulo).digest('hex'),
68:   sha256Oraculo:createHash('sha256').update(readFileSync(new URL(import.meta.url))).digest('hex'),
69:   bancoOriginalSinCambios:true,produccionModificada:false,
70:   limite:'Cierre ACL del auxiliar y llamadas SQL con roles/claims sintéticos; no vincula cotitulares neutrales ni cambia el PDF.',
71: },null,2)+'\n',{flag:'wx'});
72: console.log(`Cotitularidad: ${pruebas.length} grupos de puerta conformes.`);

